head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.nPreRow = -1;
scwin.vISUR_CD21301 = "";
scwin.vISUR_NM21301 = "";
scwin.add_gb21301 = "";

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    txb_param1.hide();
    txb_param2.hide();
    txb_KEY.hide();
    txb_PREPAY_NO.hide();
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_PayInfo.removeAll();
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달값을 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name listPrepayChg
 * @description 선납잔액 조회
 * @param {String} ISUR_CD ISUR_CD
 * @param {String} COM_NM COM_NM
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listPrepayChg = async function(ISUR_CD, COM_NM) {
    // 데이터셋 초기화
    // fn_InitDs();

    // 입력 후 재조회를 위해 세팅
    // if (add_gb21301 == "SEARCH") {
    if (ISUR_CD === "NODATA") {
        ISUR_CD = scwin.vISUR_CD21301;
        txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
        txb_COM_NM.setValue(scwin.vISUR_NM21301);
    } else {
        // 전역변수 세팅
        scwin.vISUR_CD21301 = ISUR_CD;
        // alert("전역변수vISUR_CD21301 :"+vISUR_CD21301);
        scwin.vISUR_NM21301 = COM_NM;
    }

    // alert(vISUR_CD21301+'_'+vISUR_NM21301);

    // Lodaing~~~ 표시

    // 선납잔액 조회
    url += "&SCREN_ID=" + "ULDINS21302.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (ISUR_CD === "NODATA") {
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    } else {
        url += "&ISUR_CD=" + ISUR_CD;
    }
    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listPrepayChg3
 * @description 선납금 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listPrepayChg3 = async function() {
    // 선납금등록내역 Grid 조회
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SDATE=" + "";
    url += "&EDATE=" + "";
    url += "&SCREN_ID=" + "ULDINS21302.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_PayInfo",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_PayInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listPrepayChg2
 * @description 선납금 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listPrepayChg2 = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // Lodaing~~~ 표시

    // 선납금등록내역 Grid 조회
    url += "&ISUR_CD=" + "00000";
    url += "&SDATE=" + "";
    url += "&EDATE=" + "";
    url += "&SCREN_ID=" + "ULDINS21302.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_PayInfo",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_PayInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name ins_Insert
 * @description 선납금 입력
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Insert = async function() {
    // 사전체크
    if (!await scwin.inputCheck("insert")) {
        return;
    }

    // 입력값 체크(Panel_2)
    if (rdo_PARAM.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "선급환급구분"));
        rdo_PARAM.focus();
        return;
    }
    if (edt_SDATE.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "선납/환급일"));
        edt_SDATE.focus();
        return;
    }
    if ($c.bns.fn_CheckDateObj(edt_SDATE, "선납/환급일")) return;
    if (edt_IO_AMT.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "선납/환급금액"));
        edt_IO_AMT.focus();
        return;
    }
    if (rdo_PARAM.getValue() === "R") {
        // 환급
        let vPrepayBal = 0;
        if (txb_PREPAY_BAL.getValue() === "") {
            await $c.win.alert("환급할 잔액이 없습니다.");
            rdo_PARAM.focus();
            return;
        } else {
            vPrepayBal = parseInt(txb_PREPAY_BAL.getValue());
        }
        if (parseInt(edt_IO_AMT.getValue()) > vPrepayBal) {
            // 환급금액이 잔액보다 큰 경우는 마이너스가 되서 안됨
            await $c.win.alert("환급금액이 잔액보다 큽니다.");
            edt_IO_AMT.focus();
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txa_REF_CONTN, 200, "비고")) {
        txa_REF_CONTN.focus();
        return false;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }

    // 전역변수 세팅
    scwin.vISUR_CD21301 = txb_ISUR_CD.getValue();
    scwin.vISUR_NM21301 = txb_COM_NM.getValue();
    scwin.add_gb21301 = "SEARCH";
    trs_Save.KeyName = "toinb_dataid4";
    // trs_Save.KeyValue="JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail)";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/PrepayInfoAction.do",
        ref : "dts_PayInfo",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name inputCheck
 * @description 사전체크
 * @param {*} pGubun pGubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function(pGubun) {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_COM_NM.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명"));
        txb_COM_NM.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name new
 * @description 신규버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.new = function() {
    dts_PayInfo.insertRow();
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "PREPAY_IO_TP_CD", rdo_PARAM.getValue());
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "IO_OCCR_DD", edt_SDATE.getValue());
    // alert("edt_IO_AMT: "+getObjectValue(edt_IO_AMT));
    edt_IO_AMT.setValue(edt_IO_AMT.getValue() * (-1));
    if (edt_IO_AMT.getValue() < "0") {
        // 음수로 입력한 경우 양수로 전환
        edt_IO_AMT.setValue(edt_IO_AMT.getValue() * (-1));
    }
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "IO_AMT", edt_IO_AMT.getValue());
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "MEMO_CONTN", txa_REF_CONTN.getValue());

    // alert("확인");
    txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
    txb_COM_NM.setValue(scwin.vISUR_NM21301);
};

/**
 * @method
 * @name changeInit
 * @description change Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeInit = function() {
    // 발행기관 변경시 데이터 초기화
    // setObjectValue(txb_PREPAY_BAL, "");
    rdo_PARAM.setValue("");
    edt_SDATE.setValue("");
    edt_IO_AMT.setValue("");
    txb_AmtHan.setValue("");
    txa_REF_CONTN.setValue("");
};

/**
 * @method
 * @name iusrcdsetting
 * @description iusrcdsetting 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.iusrcdsetting = async function() {
    await $c.win.alert("선납금 정보가 없습니다. 신규로 입력해주세요");
    txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
    txb_COM_NM.setValue(scwin.vISUR_NM21301);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    scwin.init();
};

/**
 * @method
 * @name dts_detail_OnLoadError
 * @description dts_detail 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadError = async function() {
    await $c.win.alert(dts_detail);
};

/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = async function() {
    if (txb_PREPAY_BAL.getValue() === "") {
        await scwin.listPrepayChg2(); // 신규
        await scwin.iusrcdsetting();
    } else {
        await scwin.listPrepayChg3(); // 기존선급금 존재기관

    }
};

/**
 * @method
 * @name dts_PayInfo_OnLoadError
 * @description dts_PayInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PayInfo_OnLoadError = async function() {
    await $c.win.alert(dts_PayInfo);
};

/**
 * @method
 * @name dts_PayInfo_OnLoadCompleted
 * @description dts_PayInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PayInfo_OnLoadCompleted = async function(rowcount) {
    if (dts_PayInfo.errorMsg) {
        await $c.win.alert(dts_PayInfo.errorMsg);
    } else {
        if (txb_PREPAY_BAL.getValue() === "") {
            txb_TotalCnt.setValue("총 0건"); // 신규

        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건"); // 기존선급금 존재기관

        }
    }

    // 데이터가 없는 경우
    // if( rowcount == 0 ){
    //    fn_CtrlBtn_temp("no_data");
    // }

};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    scwin.new();
    await scwin.ins_Insert();
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    await $c.win.alert("등록이 완료되었습니다.");
    await scwin.listPrepayChg("NODATA", "NODATA");
    scwin.changeInit();
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_COM_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};

/**
 * @method
 * @name dts_PayInfo_OnRowPosChanged
 * @description Pay Info On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_PayInfo_OnRowPosChanged = function(row) {
    dts_PayInfo.undoRow(scwin.nPreRow);
    scwin.nPreRow = row;
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_ISUR_CD_onkeypress
 * @description txb_ISUR_CD onkeypress 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeypress = function() {
    if (window.event.keyCode === 13) ins_popupOpen(txb_ISUR_CD, txb_COM_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};

/**
 * @method
 * @name edt_IO_AMT_onkeyup
 * @description 한글금액표기
 * @param {*} keycode keycode
 * @param {*} skeycode skeycode
 * @returns {void}
 * @hidden N
 */
scwin.edt_IO_AMT_onkeyup = function(keycode, skeycode) {
    // 한글금액표기
    txb_AmtHan.setValue($c.bns.fn_ChgAmtToHan(edt_IO_AMT.getValue()));
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};
